questionvariables.text:
/* Define Pythagorean triples */
pythagorean_triples : [ [3,4,5], [5,12,13], [8,15,17], [7,24,25], [9,40,41], [11,60,61], [12,35,37], [13,84,85], [16,63,65], [20,21,29], [28,45,53], [33,56,65], [36,77,85], [39,80,89], [48,55,73], [65,72,97], [6,8,10], [9,12,15], [10,24,26], [14,48,50], [18,24,30], [20,48,52], [27,36,45], [30,40,50], [45,60,75], [60,80,100] ];

/* Randomly select THREE distinct triples */
selected_triplets : rand_selection(pythagorean_triples, 3);
trip1 : selected_triplets[1]; trip2 : selected_triplets[2]; trip3 : selected_triplets[3];
val_letter1 : rand([a,b,c,d,f,w,x]); val_letter2 : rand([g,h,j,k,l,m,v,y]); val_letter3 : rand([n,p,q,r,s,t,u,z]);

/* --- Triangle 1: Cosine --- */
opp1 : trip1[1]; adj1 : trip1[2]; hyp1 : trip1[3];
angle_deg1 : float(acos(adj1/hyp1) * 180/%pi);
disp_angle1 : dispdp(angle_deg1, 4);
ta1 : dispdp(angle_deg1, 2);
mistake1 : float(asin(opp1/hyp1) * 180/%pi); /* Student used Sine instead of Cosine */

/* --- Triangle 2: Sine --- */
opp2 : trip2[1]; adj2 : trip2[2]; hyp2 : trip2[3];
angle_deg2 : float(asin(opp2/hyp2) * 180/%pi);
disp_angle2 : dispdp(angle_deg2, 4);
ta2 : dispdp(angle_deg2, 2);
mistake2 : float(acos(adj2/hyp2) * 180/%pi); /* Student used Cosine instead of Sine */

/* --- Triangle 3: Tangent --- */
opp3 : trip3[1]; adj3 : trip3[2]; hyp3 : trip3[3];
angle_deg3 : float(atan(opp3/adj3) * 180/%pi);
disp_angle3 : dispdp(angle_deg3, 4);
ta3 : dispdp(angle_deg3, 2);
mistake3 : float(asin(opp3/hyp3) * 180/%pi); /* Student used Sine instead of Tangent */
